using System;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CharacterDice", menuName = "Data/Characters/Dice")]
public class CharacterDice : ScriptableObject
{
	[Serializable]
	public class StarterDiceSetInfo
	{
		public string SetId;

		public List<InventoryItem> inventoryItemList;
	}

	[Serializable]
	public class ModStarterDiceSetsInfo
	{
		public string PublishedId;

		public List<StarterDiceSetInfo> StarterDiceSetInfosList;

		public ModStarterDiceSetsInfo(string publishedId)
		{
			PublishedId = publishedId;
			StarterDiceSetInfosList = new List<StarterDiceSetInfo>();
		}
	}

	[Header("Default Dice")]
	public List<InventoryItem> DefaultInventoryItems = new List<InventoryItem>();

	[Header("Custom Dice")]
	public List<ModStarterDiceSetsInfo> CustomInventoryItemsList = new List<ModStarterDiceSetsInfo>();
}
